  }
  if(!productData&&present(p.customsTariff))result+='<PRODUCT_LOGISTIC_DETAILS><CUSTOMS_TARIFF_NUMBER>'+element('CUSTOMS_NUMBER',p.customsTariff)+'</CUSTOMS_TARIFF_NUMBER></PRODUCT_LOGISTIC_DETAILS>';
