    attempts:Number.isInteger(row.state?.attempt) && row.state.attempt >= 0 && row.state.attempt <= 100 ? row.state.attempt : 0,
    nextRetryAt:state === 'RETRY' && next !== null ? new Date(next).toISOString() : null,
